// Проверка Portal API. Дополняет Uptime Kuma: дёшево и в том же чате.
// Шлём одно сообщение при падении, повтор каждые 30 минут пока лежит, и одно — при восстановлении.
const P = $('Параметры').first().json;
if (!P.chat_id || String(P.chat_id).includes('REPLACE')) throw new Error('Параметры → chat_id не задан');
const r = $input.first().json;
const ok = !r.error && Number(r.statusCode) === 200 && r.body && r.body.status === 'ok';
const store = $getWorkflowStaticData('global');
const now = Date.now();
const out = [];
if (!ok) {
  const reason = r.error ? (r.error.message || JSON.stringify(r.error)) : `HTTP ${r.statusCode}`;
  if (!store.downSince) { store.downSince = now; store.lastAlert = now; out.push(msg(`🔴 <b>Portal API не отвечает</b>\n${esc(reason)}`)); }
  else if (now - store.lastAlert >= 30 * 60000) { store.lastAlert = now; out.push(msg(`🔴 <b>Portal API всё ещё лежит</b> (${Math.round((now - store.downSince) / 60000)} мин)\n${esc(reason)}`)); }
} else if (store.downSince) {
  out.push(msg(`✅ <b>Portal API снова отвечает</b> (лежал ${Math.round((now - store.downSince) / 60000)} мин)`));
  delete store.downSince; delete store.lastAlert;
}
function esc(s) { return String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function msg(text) { return { json: { chat_id: String(P.chat_id), text } }; }
return out;
